export const c12EngV6HtmlOverview = "\n<style>\n  p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; line-height: 1.8; color: #E2E8F0; max-width: 950px; margin: 0 auto; padding: 12px; font-size: 15.5px;\">\n\n  <!-- Chapter Header Badge -->\n  <div style=\"background: linear-gradient(135deg, rgba(100, 221, 23, 0.22), rgba(76, 175, 80, 0.1)); border: 1.5px solid #64DD17; border-radius: 12px; padding: 20px; margin-bottom: 25px; box-shadow: 0 4px 22px rgba(100, 221, 23, 0.15);\">\n    <div style=\"display: flex; align-items: center; gap: 10px; margin-bottom: 8px;\">\n      <span style=\"background: #64DD17; color: #000; font-size: 12px; font-weight: 800; padding: 4px 10px; border-radius: 6px; letter-spacing: 0.5px;\">VISTAS &bull; CHAPTER 6</span>\n      <span style=\"color: #94A3B8; font-size: 13.5px; font-weight: 600;\">CLASS XII ENGLISH CORE (SUPPLEMENTARY READER)</span>\n    </div>\n    <h1 style=\"color: #FFFFFF; font-size: 26px; font-weight: 900; margin: 0 0 6px 0; letter-spacing: -0.5px;\">Memories of Childhood</h1>\n    <p style=\"color: #CBD5E1; font-size: 15px; margin: 0; font-style: italic;\">\n      By Zitkala-Sa &amp; Bama &mdash; Racial Assimilation, Caste Oppression &amp; Education as the Ultimate Emancipation\n    </p>\n  </div>\n\n  <!-- Quick Glossary & Chapter Dossier Card -->\n  <div style=\"background: rgba(15, 23, 42, 0.92); border: 1.5px solid rgba(100, 221, 23, 0.4); border-radius: 10px; padding: 18px 20px; margin-bottom: 25px; box-shadow: 0 4px 20px rgba(0,0,0,0.35);\">\n    <h3 style=\"color: #64DD17; font-size: 18px; margin: 0 0 12px 0; display: flex; align-items: center; gap: 8px;\">\n      <span>📖</span> Quick Glossary &amp; Chapter Dossier: Memories of Childhood\n    </h3>\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; font-size: 14px; color: #CBD5E1;\">\n      <div><b style=\"color: #64DD17;\">Part I Author:</b> Zitkala-Sa (Gertrude Simmons Bonnin, 1876&ndash;1938, Yankton Dakota)</div>\n      <div><b style=\"color: #64DD17;\">Part II Author:</b> Bama (Faustina Mary Fatima Rani, b. 1958, Tamil Dalit writer)</div>\n      <div><b style=\"color: #64DD17;\">Genre:</b> Autobiographical Memoirs / Resistance Narratives</div>\n      <div><b style=\"color: #64DD17;\">Setting I:</b> Carlisle Indian Industrial School, Pennsylvania, USA</div>\n      <div><b style=\"color: #64DD17;\">Setting II:</b> Rural Tamil Nadu Village, Southern India</div>\n      <div><b style=\"color: #64DD17;\">Core Motif I:</b> Forced cultural assimilation &amp; loss of tribal indigenous identity</div>\n      <div><b style=\"color: #64DD17;\">Core Motif II:</b> Caste untouchability, social degradation &amp; academic empowerment</div>\n      <div><b style=\"color: #64DD17;\">Guiding Maxim:</b> <i>\"Study with care, learn all you can... people will attach themselves to you.\"</i></div>\n    </div>\n  </div>\n\n  <!-- Section 1: Executive Summary & Context -->\n  <h2 style=\"color: #64DD17; font-size: 20px; font-weight: 800; border-bottom: 2px solid #64DD17; padding-bottom: 6px; margin: 28px 0 16px 0;\">\n    1. Executive Summary &amp; Dual Memoir Framework\n  </h2>\n  <p>\n    <b style=\"color: #64DD17;\">'Memories of Childhood'</b> presents two deeply poignant autobiographical accounts from two marginalized women writers living in different hemispheres and distinct historical eras: <b style=\"color: #64DD17;\">Zitkala-Sa</b>, a Native American writer and activist of the Yankton Dakota tribe, and <b style=\"color: #64DD17;\">Bama</b>, a contemporary Tamil Dalit writer and educator.\n  </p>\n  <p>\n    Despite their geographical and cultural separation, both narratives form a unified indictment of institutionalized human oppression and social cruelty. In Part I (<i>'The Cutting of My Long Hair'</i>), Zitkala-Sa depicts the traumatic cultural erasure inflicted upon indigenous American children in colonial boarding schools designed to strip them of their language, clothing, and spiritual traditions. In Part II (<i>'We Too Are Human Beings'</i>), Bama recounts her childhood discovery of caste untouchability in rural India and her elder brother Annan's transformative advice that academic excellence is the singular weapon to dismantle social inequality. Together, these memoirs celebrate human dignity, fierce resistance against subjugation, and education as the supreme vehicle for liberation.\n  </p>\n\n  <!-- Section 2: Chronological Narrative Architecture -->\n  <h2 style=\"color: #64DD17; font-size: 20px; font-weight: 800; border-bottom: 2px solid #64DD17; padding-bottom: 6px; margin: 30px 0 16px 0;\">\n    2. Chronological &amp; Thematic Narrative Architecture\n  </h2>\n\n  <!-- Part I -->\n  <h3 style=\"color: #64DD17; font-size: 18px; margin-top: 22px; border-left: 4px solid #64DD17; padding-left: 10px;\">\n    Part I: The Cutting of My Long Hair (Zitkala-Sa)\n  </h3>\n\n  <h4 style=\"color: #64DD17; font-size: 16px; margin-top: 16px;\">(i) The Cold Regimentation of Carlisle Indian School</h4>\n  <p>\n    Zitkala-Sa recounts her first bitter day at the Carlisle Indian Industrial School in Pennsylvania. The harsh, clamoring metal bell, the cold snow covering the ground, and the strict militaristic discipline feel like a violent assault upon her senses. She is stripped of her soft buckskin moccasins and traditional loose tribal blanket, forced instead into squeaking stiff leather shoes and tight, form-fitting dresses that violate her tribe's sense of modesty.\n  </p>\n\n  <h4 style=\"color: #64DD17; font-size: 16px; margin-top: 16px;\">(ii) The Humiliation in the Dining Hall</h4>\n  <p>\n    In the dining room, a small bell rings and the students march in. Zitkala-Sa pulls out her chair and sits down, but notices that everyone else remains standing. When she begins to rise in embarrassment, a second bell rings and everyone else sits down. Confused and terrified, she remains seated. When a third bell rings and everyone begins eating with knives and forks, she breaks down in helpless tears at this alien, mechanical regimentation.\n  </p>\n\n  <h4 style=\"color: #64DD17; font-size: 16px; margin-top: 16px;\">(iii) Judewin's Warning &amp; Dakota Tribal Beliefs</h4>\n  <p>\n    Her Native friend <b style=\"color: #64DD17;\">Judewin</b>, who understands a few words of English, warns her that the pale-faced matron intends to cut their long, beautiful hair. Zitkala-Sa is horrified: in Dakota culture, long hair is a sacred emblem of warrior courage and tribal honor; short hair is worn exclusively by mourners, and shingled hair by cowards captured in battle. Judewin resigns herself, saying they must submit to the white authorities. Zitkala-Sa fiercely refuses: <i>\"No, I will not submit! I will struggle first!\"</i>\n  </p>\n\n  <h4 style=\"color: #64DD17; font-size: 16px; margin-top: 16px;\">(iv) The Hidden Sanctuary &amp; The Forced Shearing</h4>\n  <p>\n    Zitkala-Sa quietly slips away upstairs, entering a large, dim room with rows of beds covered in white curtains. She crawls beneath a bed and cowers in the dark shadows. Soon, loud voices call her name; heavy footsteps enter the room; bed curtains are torn aside, and flashlights pierce the gloom. She is dragged out, carried downstairs, and strapped tightly into a chair.\n  </p>\n  <p>\n    Despite her desperate thrashing and crying, she feels the cold steel blades of the scissors bite into the base of her neck. As her thick braids fall heavily to the floor, she feels her soul crushed. She loses all spirit, feeling like a captive animal herded by an unfeeling master.\n  </p>\n\n  <!-- Part II -->\n  <h3 style=\"color: #64DD17; font-size: 18px; margin-top: 26px; border-left: 4px solid #64DD17; padding-left: 10px;\">\n    Part II: We Too Are Human Beings (Bama)\n  </h3>\n\n  <h4 style=\"color: #64DD17; font-size: 16px; margin-top: 16px;\">(i) The Innocent Schoolgirl's Daily Journey</h4>\n  <p>\n    Bama was studying in the third grade in a rural Tamil Nadu village. Although the physical distance from school to her house was barely a ten-minute walk, it habitually took her thirty to forty minutes to return home. Her childhood eyes were dazzled by the vibrant kaleidoscope of rural street life: dancing monkeys, snake charmers, cycling stuntmen, temple festivals, sweetmeat stalls, sugar-cane crushers, and drying grains.\n  </p>\n\n  <h4 style=\"color: #64DD17; font-size: 16px; margin-top: 16px;\">(ii) The Grotesque Spectacle of Untouchability</h4>\n  <p>\n    One afternoon, Bama observes a scene that initially strikes her as pure slapstick comedy. An elder from her own Dalit community&mdash;a dignified, elderly man&mdash;arrives carrying a small packet containing vadai or green-banana bhajji by its string, holding it far away from his body without touching the wrapping paper. He bows low and presents it obsequiously to the wealthy upper-caste Naicker landlord sitting on the stone ledge of his estate.\n  </p>\n  <p>\n    Bama bursts into giggles, rushing home to tell her elder brother <b style=\"color: #64DD17;\">Annan</b> about the funny old man who held food by a string like a puppet.\n  </p>\n\n  <h4 style=\"color: #64DD17; font-size: 16px; margin-top: 16px;\">(iii) Annan's Revelatory Explanation</h4>\n  <p>\n    Annan does not laugh. In solemn, pained tones, he reveals the grotesque truth of caste apartheid: the upper-caste landlord believed that if an 'untouchable' touched the food wrapping, the food would be polluted. The elder held it by the string out of forced subservience to avoid polluting the landlord's snack.\n  </p>\n\n  <h4 style=\"color: #64DD17; font-size: 16px; margin-top: 16px;\">(iv) Righteous Indignation &amp; The Path of Resistance</h4>\n  <p>\n    Hearing this, Bama's amusement instantly curdles into white-hot rage and deep humiliation. Why should her hardworking people bow down and suffer humiliation from landlords whose only achievement was being born with money and upper-caste status?\n  </p>\n  <p>\n    Annan then imparts his life-defining counsel: <i>\"Because we are born into this community, we are never given any honour or dignity or respect; we are stripped of all that. But if we study and make progress, we can throw away these indignities. So study with care, learn all you can... If you are always ahead in your lessons, people will come to you of their own accord and attach themselves to you.\"</i>\n  </p>\n  <p>\n    Annan's words became the guiding star of Bama's life. She studied with fierce devotion, stood first in her class, and won numerous friends, using education as a powerful weapon to reclaim her human dignity.\n  </p>\n\n  <!-- Section 3: Psychological Character Profiles -->\n  <h2 style=\"color: #64DD17; font-size: 20px; font-weight: 800; border-bottom: 2px solid #64DD17; padding-bottom: 6px; margin: 30px 0 16px 0;\">\n    3. Key Protagonists &amp; Guiding Figures\n  </h2>\n\n  <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 16px; margin-bottom: 25px;\">\n    \n    <!-- Zitkala-Sa -->\n    <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(100, 221, 23, 0.3); border-radius: 8px; padding: 16px;\">\n      <h3 style=\"color: #64DD17; font-size: 17px; margin: 0 0 8px 0;\">1. Zitkala-Sa (The Defiant Rebel)</h3>\n      <p style=\"font-size: 14px; margin: 0; color: #CBD5E1;\">\n        A proud Native American girl fiercely attached to her tribal heritage. Unlike her submissive friend Judewin, Zitkala-Sa refuses to surrender her identity without a struggle. She crawls under the bed and thrashes against her captors, embodying the unyielding spirit of indigenous resistance against cultural genocide.\n      </p>\n    </div>\n\n    <!-- Bama -->\n    <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(100, 221, 23, 0.3); border-radius: 8px; padding: 16px;\">\n      <h3 style=\"color: #64DD17; font-size: 17px; margin: 0 0 8px 0;\">2. Bama (The Curious Child Turned Activist)</h3>\n      <p style=\"font-size: 14px; margin: 0; color: #CBD5E1;\">\n        An innocent, joyful third-grader fascinated by village life. When she discovers the systemic cruelty of untouchability, her childlike innocence transforms into righteous fury. Channeling her anger into academic brilliance, she becomes a trailblazing voice for Dalit literature.\n      </p>\n    </div>\n\n    <!-- Annan -->\n    <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(100, 221, 23, 0.3); border-radius: 8px; padding: 16px;\">\n      <h3 style=\"color: #64DD17; font-size: 17px; margin: 0 0 8px 0;\">3. Annan (The Visionary Mentor)</h3>\n      <p style=\"font-size: 14px; margin: 0; color: #CBD5E1;\">\n        Bama's elder brother, a thoughtful university student. Having experienced caste prejudice while using the town library, he recognizes that violence or complaints cannot destroy feudal bigotry. He directs Bama toward academic excellence as the true engine of social emancipation.\n      </p>\n    </div>\n\n  </div>\n\n  <!-- Section 4: Literary & Rhetorical Devices Master Table -->\n  <h2 style=\"color: #64DD17; font-size: 20px; font-weight: 800; border-bottom: 2px solid #64DD17; padding-bottom: 6px; margin: 30px 0 16px 0;\">\n    4. Literary &amp; Rhetorical Devices Master Table\n  </h2>\n  <div style=\"overflow-x: auto; margin-bottom: 25px;\">\n    <table style=\"width: 100%; border-collapse: collapse; font-size: 14.5px; text-align: left; background: rgba(15, 23, 42, 0.9); border-radius: 8px; overflow: hidden;\">\n      <thead>\n        <tr style=\"background: rgba(100, 221, 23, 0.25); color: #FFFFFF; border-bottom: 2px solid #64DD17;\">\n          <th style=\"padding: 12px 14px;\">Literary Device</th>\n          <th style=\"padding: 12px 14px;\">Textual Quote / Example</th>\n          <th style=\"padding: 12px 14px;\">Literary &amp; Thematic Effect</th>\n        </tr>\n      </thead>\n      <tbody>\n        <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.08);\">\n          <td style=\"padding: 12px 14px; font-weight: bold; color: #64DD17;\">Symbolism</td>\n          <td style=\"padding: 12px 14px;\">Long braids (sacred tribal honor) vs. Shingled hair (cowardice &amp; defeat).</td>\n          <td style=\"padding: 12px 14px; color: #CBD5E1;\">Hair-cutting represents the violent destruction of cultural identity and forced colonial subjugation.</td>\n        </tr>\n        <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.08);\">\n          <td style=\"padding: 12px 14px; font-weight: bold; color: #64DD17;\">Dramatic Tone Shift</td>\n          <td style=\"padding: 12px 14px;\">Bama's playful giggles watching the elder holding food by string &rarr; Burning humiliation upon learning the truth.</td>\n          <td style=\"padding: 12px 14px; color: #CBD5E1;\">Highlights the tragic loss of childhood innocence when confronted with feudal discrimination.</td>\n        </tr>\n        <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.08);\">\n          <td style=\"padding: 12px 14px; font-weight: bold; color: #64DD17;\">Sensory &amp; Auditory Imagery</td>\n          <td style=\"padding: 12px 14px;\">Clamoring metal bells, squeaking shoes, the cold scissor blades biting the neck.</td>\n          <td style=\"padding: 12px 14px; color: #CBD5E1;\">Evokes the visceral terror and cold institutional regimentation experienced by indigenous children.</td>\n        </tr>\n        <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.08);\">\n          <td style=\"padding: 12px 14px; font-weight: bold; color: #64DD17;\">Visual Juxtaposition</td>\n          <td style=\"padding: 12px 14px;\">Dignified, hardworking Dalit elder bowing low vs. Idle, wealthy Naicker landlord sitting on the stone ledge.</td>\n          <td style=\"padding: 12px 14px; color: #CBD5E1;\">Exposes the profound moral injustice of caste hierarchy based purely on birth and wealth.</td>\n        </tr>\n      </tbody>\n    </table>\n  </div>\n\n  <!-- Section 5: Board Exam Strategy & High-Scoring Tips Box -->\n  <div style=\"background: rgba(15, 23, 42, 0.92); border-left: 5px solid #64DD17; border-radius: 8px; padding: 18px 20px; margin-bottom: 25px; box-shadow: 0 4px 20px rgba(0,0,0,0.3);\">\n    <h3 style=\"color: #64DD17; font-size: 18px; margin: 0 0 10px 0; display: flex; align-items: center; gap: 8px;\">\n      <span>🎯</span> Board Examination Master Tips: Scoring 100% in Memories of Childhood\n    </h3>\n    <ul style=\"color: #CBD5E1; font-size: 14.5px; padding-left: 20px; margin: 0; line-height: 1.8;\">\n      <li><b style=\"color: #64DD17;\">Compare Both Narratives:</b> In 6-mark thematic questions, draw clear parallels between Zitkala-Sa's <b style=\"color: #64DD17;\">racial assimilation</b> in America and Bama's <b style=\"color: #64DD17;\">caste oppression</b> in India.</li>\n      <li><b style=\"color: #64DD17;\">Quote Annan's Words:</b> Always cite Annan's advice on education: <i>\"Study with care, learn all you can... people will attach themselves to you.\"</i></li>\n      <li><b style=\"color: #64DD17;\">Dakota Hair Traditions:</b> Clearly mention that in Dakota culture, short hair was worn by mourners and shingled hair by cowards.</li>\n    </ul>\n  </div>\n\n</div>\n";

